async function main() {
  const prisma = new PrismaClient();

  const category = await prisma.interviewCategory.upsert({
    where: { slug: "behavioral-hr" },
    update: { name: "Behavioral / HR" },
    create: { name: "Behavioral / HR", slug: "behavioral-hr" },
  });

  const subcategoryNames: Record<string, string> = {
    "teamwork-collaboration": "Teamwork & Collaboration",
    "communication-conflict-feedback": "Communication, Conflict & Feedback",
    "ownership-accountability-initiative": "Ownership, Accountability & Initiative",
    "adaptability-learning-problem-solving": "Adaptability, Learning & Problem Solving",
    "prioritization-leadership-decision-making": "Prioritization, Leadership & Decision-Making",
  };

  const subcategories: Record<string, any> = {};
  for (const [slug, name] of Object.entries(subcategoryNames)) {
    subcategories[slug] = await prisma.interviewSubcategory.upsert({
      where: { categoryId_slug: { categoryId: category.id, slug } },
      update: { name },
      create: { name, slug, categoryId: category.id },
    });
  }

  for (const item of records) {
    const subcategory = subcategories[item.subcategorySlug];

    await prisma.interviewQuestion.upsert({
      where: { slug: item.slug },
      update: {
        question: item.question,
        categoryId: category.id,
        subcategoryId: subcategory.id,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        isPublished: true,
      },
      create: {
        question: item.question,
        slug: item.slug,
        categoryId: category.id,
        subcategoryId: subcategory.id,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        isPublished: true,
      },
    });
  }

  console.log(`Seeded ${records.length} Behavioral / HR interview questions.`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exit(1);
  })
